docutils.parsers.rst.roles.raw_role:
def raw_role(role, rawtext, text, lineno, inliner, options=None, content=None):
    options = normalize_options(options)
    if not inliner.document.settings.raw_enabled:
        msg = inliner.reporter.warning('raw (and derived) roles disabled')
        prb = inliner.problematic(rawtext, rawtext, msg)
        return ([prb], [msg])
    if 'format' not in options:
        msg = inliner.reporter.error('No format (Writer name) is associated with this role: "%s".\nThe "raw" role cannot be used directly.\nInstead, use the "role" directive to create a new role with an associated format.' % role, line=lineno)
        prb = inliner.problematic(rawtext, rawtext, msg)
        return ([prb], [msg])
    node = nodes.raw(rawtext, nodes.unescape(text, True), **options)
    (node.source, node.line) = inliner.reporter.get_source_and_line(lineno)
    return ([node], [])

docutils.parsers.rst.roles.pep_reference:
def pep_reference_role(role, rawtext, text, lineno, inliner, options=None, content=None):
    options = normalize_options(options)
    try:
        pepnum = int(nodes.unescape(text))
        if (pepnum < 0 or pepnum > 9999):
            raise ValueError
    except ValueError:
        msg = inliner.reporter.error('PEP number must be a number from 0 to 9999; "%s" is invalid.' % text, line=lineno)
        prb = inliner.problematic(rawtext, rawtext, msg)
        return ([prb], [msg])
    ref = inliner.document.settings.pep_base_url + inliner.document.settings.pep_file_url_template % pepnum
    return ([nodes.reference(rawtext, 'PEP ' + text, refuri=ref, **options)], [])

docutils.nodes.parse_measure:
def parse_measure(measure: str, unit_pattern: str = '[a-zA-Zµ]*|%?') -> tuple[(int | float, str)]:
    """Parse a measure__, return value + unit.

    `unit_pattern` is a regular expression describing recognized units.
    The default is suited for (but not limited to) CSS3 units and SI units.
    It matches runs of ASCII letters or Greek mu, a single percent sign,
    or no unit.

    __ https://docutils.sourceforge.io/docs/ref/doctree.html#measure

    Provisional.
    """
    match = re.fullmatch(f'(-?[0-9.]+) *({unit_pattern})', measure)
    try:
        try:
            value = int(match.group(1))
        except ValueError:
            value = float(match.group(1))
        unit = match.group(2)
    except (AttributeError, ValueError):
        raise ValueError(f'"{measure}" is no valid measure.')
    return (value, unit)

docutils.nodes.validate_colwidth:
def validate_colwidth(measure: str | int | float) -> int | float:
    """Validate the "colwidth__" attribute.

    Provisional:
        `measure` must be a `str` and will be returned as normalized `str`
        (with unit "*" for proportional values) in Docutils 1.0.

        The default unit will change to "pt" in Docutils 2.0.

    __ https://docutils.sourceforge.io/docs/ref/doctree.html#colwidth
    """
    if isinstance(measure, (int, float)):
        value = measure
    elif measure in ('*', ''):
        value = 1
    else:
        try:
            (value, _unit) = parse_measure(measure, unit_pattern='[*]?')
        except ValueError:
            value = -1
    if value <= 0:
        raise ValueError(f'"{measure}" is no proportional measure.')
    return value

docutils.nodes.validate_NMTOKENS:
def validate_NMTOKENS(value: str | list[str]) -> list[str]:
    """
    Validate a list of "name tokens".

    Provisional.
    """
    if isinstance(value, str):
        value = value.split()
    for token in value:
        validate_NMTOKEN(token)
    return value

docutils.utils.math.tex2mathml_extern._c:
def _check_result(result, details=[]):
    msg = ''
    if (not details and result.stderr):
        details = [nodes.paragraph('', result.stderr, classes=['pre-wrap'])]
    if details:
        msg = f'TeX to MathML converter `{result.args[0]}` failed:'
    elif result.returncode:
        msg = f'TeX to MathMl converter `{result.args[0]}` exited with Errno {result.returncode}.'
    elif not result.stdout:
        msg = f'TeX to MathML converter `{result.args[0]}` returned no MathML.'
    if msg:
        raise MathError(msg, details=details)
